#[cfg(test)]
mod ascii_properties_tests {
    #[test]
    fn packed_ascii_properties_agree() {
        for scalar in 0..128u64 {
            let expected = super::RANGES.iter().find(|row| **row >> 37 <= scalar && scalar <= (**row >> 16 & 0x1fffff)).map_or(0, |row| *row as u16);
            assert_eq!(super::bits(char::from_u32(scalar as u32).unwrap()), expected);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    // Check stable ordering, blocking, old corrections, and surrogate preservation.
    #[test]
    fn normalization_and_versions() {
        assert!(normalize("invalid", &[], false).unwrap().is_empty());
        assert_eq!(normalize("NFC", &[0x61, 0x300, 0x327], false).unwrap(), [0xE0, 0x327]);
        assert_eq!(normalize("NFD", &[0x61, 0x300, 0x327], false).unwrap(), [0x61, 0x327, 0x300]);
        assert_eq!(normalize("NFC", &[0x1100, 0x300, 0x1161], false).unwrap(), [0x1100, 0x300, 0x1161]);
        assert_eq!(normalize("NFC", &[0xD800, 65, 0x30A, 0xDFFF], false).unwrap(), [0xD800, 0xC5, 0xDFFF]);
        assert_eq!(normalize("NFKC", &[0x1CCD6], false).unwrap(), [65]);
        assert_eq!(normalize("NFKC", &[0x1CCD6], true).unwrap(), [0x1CCD6]);
        assert_eq!(normalize("NFD", &[0x2F9BF], true).unwrap(), [0x4D57]);
        assert_eq!(decomposition(0xD7A3, false), "1112 1175 11C2");
        assert_eq!(lookup("KEYCAP NUMBER SIGN", false).unwrap(), [35, 65039, 8419]);
        assert!(lookup("LF", true).is_none());
        assert!(name(0x221, true).is_none());
    }
    // Exercise the UCD boundary rules and both historical and modern forms.
    #[test]
    fn unicode_forms() {
        for (form, input, historic, expected) in [
            ("NFD", vec![0x61, 0x300, 0x327], false, vec![0x61, 0x327, 0x300]),
            ("NFC", vec![0x61, 0x300, 0x327], false, vec![0xE0, 0x327]),
            ("NFC", vec![0x1100, 0x300, 0x1161], false, vec![0x1100, 0x300, 0x1161]),
            ("NFC", vec![0xD800, 65, 0x30A, 0xDFFF], false, vec![0xD800, 0xC5, 0xDFFF]),
            ("NFKC", vec![0x1CCD6], true, vec![0x1CCD6]),
            ("NFKC", vec![0x1CCD6], false, vec![65]),
            ("NFD", vec![0x2F9BF], true, vec![0x4D57]),
        ] {
            assert_eq!(normalize(form, &input, historic).unwrap(), expected);
        }
        assert_eq!(decomposition(0xAC00, true), "1100 1161");
        assert_eq!(lookup("KEYCAP NUMBER SIGN", false), Some(vec![35, 65039, 8419]));
        assert_eq!(lookup("LF", true), None);
        assert_eq!(name(0x221, true), None);
    }
}
